draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(0, H - 50 - 20 * Math.sin(t));
  ctx.lineTo(W, H - 50 - 20 * Math.sin(t + Math.PI));
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 100);
  ctx.lineTo(W / 2 + 20 * Math.cos(t), H - 70);
  ctx.lineTo(W / 2 - 20 * Math.cos(t), H - 70);
  ctx.closePath();
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('1917', 10, 10);
  ctx.restore();
}
